<script setup lang="ts">
import {computed,ref,watch} from 'vue'
import {Play,Search,Check,Scissors,FileText} from '@lucide/vue'
import type {AnalysisView,AnalysisSelection,Job,Proposal} from '../types'
import {time} from '../format'
import AnalysisFeedback from './AnalysisFeedback.vue'
const props=defineProps<{analysis:AnalysisView|null;selection:AnalysisSelection|null;jobs:Job[];sourceUrl:string;busy:boolean}>()
const emit=defineEmits<{generate:[value:{analysis_hash:string;candidate_ids:string[]}];selection:[value:AnalysisSelection]}>()
const topic=ref(''),search=ref(''),focused=ref(''),selected=ref<string[]>([]),player=ref<HTMLVideoElement>(),playEnd=ref(0)
const locallyEdited=ref(false)
const complete=computed(()=>props.analysis?.state==='completed'&&!!props.analysis.analysis_hash)
const proposals=computed(()=>props.analysis?.proposals||[])
const filtered=computed(()=>proposals.value.filter(p=>(!topic.value||p.group_id===topic.value)&&(!search.value||[p.title,p.rationale,p.text].join(' ').toLocaleLowerCase('pt-BR').includes(search.value.toLocaleLowerCase('pt-BR')))))
const current=computed(()=>filtered.value.find(p=>p.candidate_id===focused.value)||filtered.value[0])
const validSelection=computed(()=>selected.value.filter(id=>proposals.value.some(p=>p.candidate_id===id&&p.eligible)))
const overlap=computed(()=>validSelection.value.some((id,i)=>validSelection.value.slice(i+1).some(other=>{const a=proposals.value.find(p=>p.candidate_id===id)!,b=proposals.value.find(p=>p.candidate_id===other)!;return Math.min(a.end_us,b.end_us)>Math.max(a.start_us,b.start_us)})))
watch(()=>props.analysis?.analysis_hash,(hash,old)=>{if(hash!==old){locallyEdited.value=false;selected.value=hash&&props.selection?.analysis_hash===hash?[...props.selection.candidate_ids]:[];if(!proposals.value.some(p=>p.candidate_id===focused.value))focused.value='';if(!props.analysis?.topic_groups.some(g=>g.id===topic.value))topic.value=''}})
watch(()=>props.analysis?.job_id,(job,old)=>{if(old&&job!==old){focused.value='';topic.value='';selected.value=[];locallyEdited.value=false}})
watch(()=>props.selection,value=>{if(!locallyEdited.value&&value?.analysis_hash===props.analysis?.analysis_hash&&value?.analysis_hash)selected.value=[...value.candidate_ids]},{immediate:true})
function toggle(p:Proposal){if(!complete.value||!p.eligible||props.busy)return;locallyEdited.value=true;selected.value=selected.value.includes(p.candidate_id)?selected.value.filter(id=>id!==p.candidate_id):[...selected.value,p.candidate_id];emit('selection',{schema_version:'1.0',analysis_hash:props.analysis!.analysis_hash,candidate_ids:[...validSelection.value]})}
function play(context=false){if(!player.value||!current.value)return;player.value.currentTime=Math.max(0,current.value.start_us/1e6-(context?15:0));playEnd.value=(current.value.end_us/1e6)+(context?15:0);player.value.play().catch(()=>{})}
function stopAtEnd(){if(player.value&&playEnd.value&&player.value.currentTime>=playEnd.value){player.value.pause();playEnd.value=0}}
function choose(id:string){focused.value=id;player.value?.pause();playEnd.value=0}
</script>
<template>
 <section class="analysis-workspace">
  <header class="analysis-heading"><div><span class="eyebrow">Conteúdo antes do formato</span><h2>Temas e propostas</h2><p v-if="analysis">{{analysis.model||'Análise ainda não iniciada'}} · {{analysis.completed_windows}}/{{analysis.total_windows}} janelas validadas · {{proposals.length}} propostas<span v-if="!complete"> · Resultado parcial</span></p><p v-else>A análise organizará os temas e os trechos da transcrição.</p></div><button class="button primary" data-action="generate-selected" :disabled="!complete||!validSelection.length||busy" @click="emit('generate',{analysis_hash:analysis!.analysis_hash!,candidate_ids:[...validSelection]})"><Scissors :size="16"/>Gerar {{validSelection.length}} prévia{{validSelection.length===1?'':'s'}}</button></header>
  <div v-if="!complete" class="notice" role="status">As propostas já validadas podem ser consultadas. A geração fica disponível quando a análise completa terminar.</div>
  <p v-if="overlap" class="notice">Você selecionou trechos com sobreposição. As versões serão geradas separadamente.</p>
  <div class="analysis-layout">
   <aside class="topic-list"><h3>Temas identificados</h3><button :class="{selected:!topic}" @click="topic='';focused=''">Todos os temas <span>{{proposals.length}}</span></button><button v-for="group in analysis?.topic_groups" :key="group.id" :class="{selected:topic===group.id}" @click="topic=group.id;focused=''">{{group.label}}<span>{{proposals.filter(p=>p.group_id===group.id).length}}</span></button><div v-if="topic" class="topic-summary"><p v-for="summary in analysis?.topic_groups.find(g=>g.id===topic)?.summaries" :key="summary">{{summary}}</p></div></aside>
   <div class="proposal-column"><label class="search"><Search :size="16"/><input v-model="search" type="search" placeholder="Buscar nas propostas" aria-label="Buscar nas propostas"/></label><div class="proposal-list hidden-scrollbar" tabindex="0" aria-label="Propostas de cortes"><article v-for="p in filtered" :key="p.candidate_id" class="proposal-card" :class="{selected:current?.candidate_id===p.candidate_id}"><div class="proposal-top"><label class="proposal-checkbox"><input type="checkbox" :checked="selected.includes(p.candidate_id)" :disabled="!complete||!p.eligible||busy" :aria-label="'Selecionar '+p.title" @change="toggle(p)"/></label><button class="proposal-open" @click="choose(p.candidate_id)"><strong>{{p.title}}</strong><small>{{time(p.start_us)}} – {{time(p.end_us)}} · {{time(p.duration_us)}}</small></button></div><p>{{p.rationale}}</p><span class="status-pill" :data-status="p.eligible?'analyzed':'failed'"><Check v-if="p.eligible" :size="12"/>{{p.eligible?'Elegível para prévia':'Precisa de atenção'}}</span></article><p v-if="!filtered.length" class="subtle empty-proposals">{{proposals.length?'Nenhuma proposta corresponde ao filtro.':'Aguardando propostas validadas.'}}</p></div></div>
   <section v-if="current" class="proposal-detail"><span class="eyebrow">Trecho no vídeo original</span><h3>{{current.title}}</h3><video v-if="sourceUrl" ref="player" :src="sourceUrl" controls preload="metadata" playsinline @timeupdate="stopAtEnd"></video><div class="proposal-play"><button class="button small primary" :disabled="!sourceUrl" @click="play()"><Play :size="14"/>Ouvir trecho</button><button class="button small secondary" :disabled="!sourceUrl" @click="play(true)">Com contexto</button></div><p class="proposal-rationale">{{current.rationale}}</p><div class="editorial-flags"><span v-for="(label,key) in {completeness:'Raciocínio completo',standalone_context:'Contexto suficiente',qualification_preserved:'Ressalvas preservadas'}" :key="key">{{label}} <b>{{current.editorial[key]==='yes'?'Sim':current.editorial[key]==='no'?'Não':'Incerto'}}</b></span></div><p v-if="!current.eligible" class="notice error">{{current.reasons.join(' ')}} A geração permanece bloqueada.</p><p v-for="warning in current.warnings" :key="warning" class="subtle">{{warning}}</p><details class="proposal-transcript" open><summary><FileText :size="14"/>Fala e contexto</summary><p class="context-text">{{current.context_before}}</p><p>{{current.text}}</p><p class="context-text">{{current.context_after}}</p></details><small>{{current.evidence_word_ids.length}} referência(s) à transcrição original · Timestamps estimados pelo ASR</small></section>
  </div>
  <details class="analysis-explanation"><summary>Resumo da análise em andamento</summary><AnalysisFeedback :jobs="jobs"/></details>
 </section>
</template>
